      "useCase": "اختبر نفاذ الإجراء، أثر الإعلان، حساب الميعاد، أو معالجة البطلان في واقعة افتراضية.",
      "sourceNotes": [],
      "text": "1. يتم الإعلان بناءً على طلب الخصم أو أمر المحكمة المختصة أو مكتب إدارة الدعوى بوساطة القائم بالإعلان أو بالطريقة التي يُحددها هذا القانون.\n2. للمحكمة المختصة أو مكتب إدارة الدعوى أو القاضي المشرف حسب الأحوال أن تصرح للمدعي أو وكيله للقيام بالإعلان بالوسائل المنصوص عليها في البند (1) من المادة (9) من هذا القانون.\n3. يجوز الإعلان بوساطة شركة أو مكتب خاص أو أكثر وفق أحكام هذا القانون، ويصدر رئيس مجلس القضاء الاتحادي أو رئيس الجهة القضائية المحلية حسب الأحوال، نظامًا خاصًا بقيام الشركات والمكاتب الخاصة لإجراء الإعلان وفق أحكام هذا القانون، ويعد قائمًا بالإعلان كل من كلف بتولي عملية الإعلان في هذا الشأن.\n4. وفي جميع الأحوال يجوز القيام بالإعلان على مستوى الدولة دون التقيد بقواعد الاختصاص المكاني.",
      "source": "قانون الإجراءات المدنية الإماراتي · المادة 6",
      "sourceUrl": "https://uaelegislation.gov.ae/ar/legislations/1602",
