      "useCase": "اختبر نفاذ الإجراء، أثر الإعلان، حساب الميعاد، أو معالجة البطلان في واقعة افتراضية.",
      "sourceNotes": [],
      "text": "يعتبر الإعلان منتجًا لآثاره وفقًا للآتي:-\n1. من تاريخ تبليغه وفقًا للأحكام الواردة في المادتين (9) و(10) من هذا القانون أو من تاريخ رفض المعلن إليه تبليغه.\n2. بعد انقضاء (21) واحد وعشرين يوم عمل تبدأ من تاريخ تبليغ البعثة الدبلوماسية المعنية في الدولة كتاب وزارة الخارجية والتعاون الدولي المتضمن للإعلان.\n3. من تاريخ وصول الفاكس، أو تاريخ إرسال البريد الإلكتروني أو رسالة الهاتف المحمول أو أي من وسائل تقنية المعلومات، أو من تاريخ تحقق المكالمة المسجلة الصوتية أو المرئية.\n4. من تاريخ إدراج الإعلان في الموقع الإلكتروني للمحكمة في الصفحة المخصصة ويستمر الإدراج لمدة لا تقل عن (15) خمسة عشر يومًا، ومن تاريخ إتمام اللصق أو النشر وفقًا للأحكام المنصوص عليها في هذا الباب.",
      "source": "قانون الإجراءات المدنية الإماراتي · المادة 11",
      "sourceUrl": "https://uaelegislation.gov.ae/ar/legislations/1602",
