      "sourceNotes": [],
      "text": "يختص القضاء المستعجل بالحكم بفرض الحراسة القضائية على منقول أو عقار أو مجموع من الأموال قام في شأنه نزاع أو كان الحق فيه غير ثابت، إذا تجمع لدى صاحب المصلحة في المال من الأسباب المعقولة ما يخشى معه خطرًا عاجلاً من بقاء المال تحت يد حائزه.",
