      "sourceNotes": [],
      "text": "1. يجوز بقرار من رئيس مجلس القضاء الاتحادي أو رئيس الجهة القضائية المحلية -كل بحسب اختصاصه- أن يحيل بعض الدعاوى إلى دائرة أو أكثر من دوائر المحاكم الابتدائية أو الاستئنافية، بحسب الأحوال، ويعاون القاضي المشرف في مرحلة تحضير الدعوى خبير أو أكثر من الخبراء المحليين أو الدوليين لمراجعة أو إعداد تقارير الخبرة التي تعرض على هذه الدوائر، وللمحكمة المختصة مناقشة الخبراء في التقارير التي قاموا بإعدادها أو مراجعتها ولها أن تأمر باستكمال أوجه النقص في عملهم وتدارك ما تتبينه من أوجه الخطأ فيه.\n2. تصدر الأحكام من الدوائر المشار إليها في البند (1) من هذه المادة بذات الإجراءات والضوابط الواردة في هذا القانون.",
