      "useCase": "حدّد المحكمة المختصة وميّز بين الاختصاص الدولي والنوعي والمحلي في ملف تدريبي.",
      "sourceNotes": [
        "وردت في المرفق عبارة «النصوص السابقة» قبل نص المادة؛ حُفظت كملاحظة مصدرية ولم تُدمج في النص التشريعي."
      ],
      "text": "1. استثناءً من أحكام الفصل الثاني والرابع من الباب الثاني عشر من الكتاب الأول من هذا القانون وأحكام قانون الوساطة والتوفيق، يجوز لرئيس مجلس القضاء الاتحادي أو رئيس الجهة القضائية المحلية، بحسب الأحوال، أن يصدر قراراً بإنشاء دائرة أو أكثر يتم تشكيلها بطريق الندب أو التعيين وفقاً للتشريعات المنظمة لكل جهة.\n2. تختص الدائرة المنصوص عليها في البند (1) من هذه المادة، بالفصل في دعاوى التركات وكافة المنازعات المتعلقة بقائمة الجرد أو تصفية التركة أو قسمة أموالها وتوزيعها بين الورثة وأي دعوى مدنية أو عقارية أو تجارية ناشئة أو متفرعة عن التركة تتعلق بملكيتها أو تصفيتها أو أي شأن من شؤونها بين الورثة والغير، والنزاعات التي تتم بين الورثة والأوصياء ومن في حكمهم، وكذلك أي طلبات عارضة متعلقة بإخراج أو إدخال وارث أو بالوصايا أو الوقف أو بالتسوية بين الورثة في الهبات تكون ناشئة عن التركة أو مرتبطة بها ارتباطاً لا يقبل التجزئة.\n3. للدائرة أن تستعين بمكتب إدارة الدعوى وقاضي التحضير المنصوص عليهما في هذا القانون.\n4. للدائرة أن تستعين بخبير أو أكثر من الخبراء المحليين أو الدوليين لمراجعة أو إعداد تقارير الخبرة التي تعرض عليها، ولها مناقشة الخبراء في التقارير التي قاموا بإعدادها أو مراجعتها، ولها أن تأمر باستكمال أوجه النقص في عملهم وتدارك ما تَتَبينه من أوجه الخطأ فيه.\n5. الحكم الصادر من الدائرة المنصوص عليها في البند (1) من هذه المادة غير قابل للطعن عليه إلا بطريق التماس إعادة النظر، كما يجوز الرجوع عن ذلك الحكم وفق الحالات والضوابط والإجراءات المنصوص عليها في هذا القانون.\n6. لرئيس مجلس القضاء الاتحادي أو رئيس الجهة القضائية المحلية، بحسب الأحوال، بناءً على طلب أو اتفاق أطراف الدعوى المدنية أو التجارية، أن يُصدر قراراً بإنشاء دائرة لنظر هذه الدعوى وفقاً لأحكام البند (1) من هذه المادة، وتسري في شأن هذه الدائرة والأحكام الصادرة عنها الأحكام المنصوص عليها في البنود (3) و(4) و(5) من هذه المادة.",
      "source": "قانون الإجراءات المدنية الإماراتي · المادة 32",
      "sourceUrl": "https://uaelegislation.gov.ae/ar/legislations/1602",
      "sourceFile": "Pasted markdown(1).md"
