      "useCase": "قدّر قيمة الدعوى وحدد ما يدخل في التقدير وما يستبعد، ثم راجع أثر ذلك على المسار الإجرائي.",
      "sourceNotes": [],
      "text": "1. ميعاد الحضور أمام مكتب إدارة الدعوى أو المحكمة المختصة (10) عشرة أيام عمل، ويجوز في حالة الضرورة إنقاص هذا الميعاد إلى (3) ثلاثة أيام عمل.\n2. ميعاد الحضور في الدعاوى المستعجلة (24) أربع وعشرون ساعة ويجوز في حالة الضرورة إنقاص هذا الميعاد بحيث لا يقل عن ساعة بشرط أن يحصل الإعلان للخصم نفسه إلا إذا كانت الدعوى من الدعاوى البحرية.\n3. يكون إنقاص المواعيد المشار إليها في البندين (1) و(2) من هذه المادة بإذن من القاضي المختص أو القاضي المشرف -بحسب الأحوال- وتعلن صورته للخصم مع صحيفة الدعوى.\n4. لا يترتب البطلان على عدم مراعاة مواعيد الحضور، وذلك بغير إخلال بحق المعلن إليه في طلب التأجيل لاستكمال الميعاد.",
      "source": "قانون الإجراءات المدنية الإماراتي · المادة 46",
      "sourceUrl": "https://uaelegislation.gov.ae/ar/legislations/1602",
