      "useCase": "قدّر قيمة الدعوى وحدد ما يدخل في التقدير وما يستبعد، ثم راجع أثر ذلك على المسار الإجرائي.",
      "sourceNotes": [],
      "text": "1. يقوم مكتب إدارة الدعوى بعد استيفاء الرسوم بقيد الدعوى في السجل الخاص بذلك -إلكترونيًّا أو ورقيًّا- على أن يثبت فيه تاريخ القيد ويسجل فيه علم المدعي بالجلسة وتعتبر الدعوى في تلك الحالة مقيدة ومنتجة لآثارها من تاريخ تقديم الصحيفة شريطة سداد الرسم خلال أجل لا يتجاوز (3) ثلاثة أيام عمل من تاريخ اليوم التالي للإشعار بالسداد وإلا اعتبر القيد كأن لم يكن.\n2. لرئيس مجلس القضاء الاتحادي أو رئيس الجهة القضائية المحلية -بحسب الأحوال- إصدار الدليل الإرشادي لنظام قيد الدعاوى والطلبات والتظلمات والطعون بما ينسجم مع القواعد المالية والإدارية والتقنية المعمول بها في كل جهة ويسهل من إجراءات وعمليات القيد.",
      "source": "قانون الإجراءات المدنية الإماراتي · المادة 47",
      "sourceUrl": "https://uaelegislation.gov.ae/ar/legislations/1602",
      "sourceFile": "Pasted markdown(1).md"
