      "useCase": "قدّر قيمة الدعوى وحدد ما يدخل في التقدير وما يستبعد، ثم راجع أثر ذلك على المسار الإجرائي.",
      "sourceNotes": [],
      "text": "1. تُقدر قيمة الدعوى يوم رفعها، وفي جميع الأحوال يكون التقدير على أساس آخر طلبات قدمها الخصوم، ويدخل في تقدير قيمة الدعوى ما يكون مستحقًا يوم رفعها من الفائدة والتضمينات والريع والمصروفات وغير ذلك من الملحقات المقدرة القيمة، ومع ذلك يعتد في جميع الأحوال بقيمة البناء أو الغراس إذا طلب إزالته.\n2. في جميع الأحوال لا يدخل في تقدير قيمة الدعوى طلب ندب الخبرة وسائر طلبات الإثبات إذا قدمت مع طلبات موضوعية أخرى.",
      "source": "قانون الإجراءات المدنية الإماراتي · المادة 50",
      "sourceUrl": "https://uaelegislation.gov.ae/ar/legislations/1602",
