      "sourceNotes": [],
      "text": "تجري المرافعة في أول جلسة، وإذا قدم المدعي أو المدعى عليه في هذه الجلسة مستندًا كان بإمكانه تقديمه في الميعاد المقرر في البند (2) من المادة (48) من هذا القانون، قبلته المحكمة إذا لم يترتب على ذلك تأجيل نظر الدعوى، فإذا ترتب على قبول المستند تأجيل الدعوى يجوز للمحكمة من تلقاء نفسها أو بناءً على طلب الخصوم أن تصدر قرارًا بتغريم المتسبب في التأجيل بمبلغ لا يقل عن (2.000) ألفي درهم ولا يجاوز (5.000) خمسة آلاف درهم، ومع ذلك يجوز لكل من المدعي والمدعى عليه أن يقدم مستندات ردًا على دفاع خصمه أو طلباته العارضة.",
      "source": "قانون الإجراءات المدنية الإماراتي · المادة 73",
