      "sourceNotes": [],
      "text": "1. لا يجوز للمحكمة تأجيل الدعوى أكثر من مرة واحدة لسبب واحد يرجع إلى أحد الخصوم إلا لسبب طارئ بعد الإحالة كوفاة أحد الخصوم أو فقد أهليته أو التدخل في الدعوى من الغير أو الطعن بالتزوير أو تقديم ما يفيد وجود دعوى جزائية مرتبطة بنفس الموضوع أو طلب أحد الخصوم تقديم ما يفيد التصالح، على ألا تجاوز فترة التأجيل أسبوعين.\n2. لا يجوز للمحكمة تأجيل الدعوى أكثر من (10) عشر جلسات مهما تعددت الأسباب.\n3. في جميع الأحوال على المحكمة إصدار الحكم المنهي للخصومة خلال فترة لا تجاوز (80) ثمانين يومًا من تاريخ أول جلسة لنظر الدعوى أمامها.",
