      "useCase": "أدر جلسة افتراضية: المستندات، المواعيد، الصلح، نظام الجلسة، والجزاءات الإجرائية.",
      "sourceNotes": [],
      "text": "للخصوم أن يطلبوا من المحكمة في أية حالة تكون عليها الدعوى إثبات ما اتفقوا عليه في محضر الجلسة، بما لا يتعارض مع التشريعات النافذة أو النظام العام والآداب العامة في الدولة، ويكون للمحضر والاتفاق الملحق به في الحالتين قوة السند التنفيذي وتعطى صورته وفقًا للقواعد المقررة لتسليم صور الأحكام.",
