      "text": "تستأنف الدعوى سيرها بالنسبة للخصم الذي قام به سبب الانقطاع بتكليف بالحضور يعلن إلى من يقوم مقام من توفي أو فقد أهلية التقاضي أو زالت صفته بناءً على طلب الطرف الآخر أو بتكليف يعلن إلى هذا الطرف بناءً على طلب أولئك، وكذلك تستأنف الدعوى سيرها إذ حضر الجلسة التي كانت محددة لنظرها ورثة المتوفى أو من يقوم مقام من فقد أهلية الخصومة أو مقام من زالت عنه الصفة وباشر السير فيها.",
