      "sourceNotes": [],
      "text": "1. لكل ذي مصلحة من الخصوم في حالة عدم السير في الدعوى بفعل المدعي أو امتناعه أن يطلب الحكم بسقوط الخصومة متى انقضت (6) ستة أشهر من آخر إجراء صحيح من إجراءات التقاضي.\n2. لا تبدأ مدة سقوط الخصومة في حالات الانقطاع إلا من اليوم الذي قام فيه من طلب الحكم بسقوط الخصومة بإعلان ورثة خصمه الذي توفي أو من قام مقام من فقد أهليته للخصومة أو مقام من زالت صفته بوجود الدعوى بينه وبين خصمه الأصلي.\n3. تسري المدة المقررة لسقوط الخصومة في حق جميع الأشخاص ولو كانوا عديمي الأهلية أو ناقصيها ولا يخل ذلك بحقهم في الرجوع على النائبين عنهم بالتعويض بسبب إهمالهم في متابعة الدعوى مما أدى إلى سقوطها.",
