      "useCase": "حلّل بنية الحكم: المداولة، الأسباب، البيانات، المنطوق، المصروفات، والتصحيح أو التفسير.",
      "sourceNotes": [],
      "text": "1. يجب في جميع الأحوال أن تشتمل الأحكام على الأسباب التي بنيت عليها، وتودع عند إصدارها في ملف الدعوى موقعة من الرئيس وأعضاء الدائرة سواءً إلكترونيًّا أو يدويًّا.\n2. يجوز في المواد المستعجلة إذا صدر الحكم في جلسة المرافعة أن يودع الحكم مشتملاً على أسبابه خلال (3) ثلاثة أيام عمل من تاريخ صدوره.\n3. يترتب على مخالفة الأحكام الواردة في البندين (1) و(2) من هذه المادة بطلان الحكم.",
      "source": "قانون الإجراءات المدنية الإماراتي · المادة 129",
      "sourceUrl": "https://uaelegislation.gov.ae/ar/legislations/1602",
