      "sourceNotes": [],
      "text": "1. يجب أن يبين في الحكم، المحكمة التي أصدرته، وتاريخ إصداره، ومكانه، ونوع الدعوى، وأسماء القضاة الذين سمعوا المرافعة وأصدروا الحكم، وأسماء الخصوم وحضورهم أو غيابهم.\n2. يجب أن يشتمل الحكم على عرض مجمل لوقائع الدعوى ثم طلبات الخصوم وخلاصة موجزة لدفاعهم الجوهري ورأي النيابة إن كان، ثم تذكر بعد ذلك أسباب الحكم ومنطوقه.\n3. القصور في أسباب الحكم الواقعية والنقص أو الخطأ الجسيم في أسماء الخصوم وصفاتهم وعدم بيان أسماء القضاة الذين أصدروا الحكم يترتب عليه بطلان الحكم.",
