      "text": "1. للمحكمة أن تحكم بالتضمينات مقابل النفقات الناشئة عن دعوى أو دفاع قصد بهما الكيد.\n2. مع عدم الإخلال بحكم المادة (133) من هذا القانون، للمحكمة عند إصدار الحكم الفاصل في الموضوع أن تحكم بغرامة لا تقل عن (1.000) ألف درهم، ولا تزيد على (10.000) عشرة آلاف درهم على الخصم الذي يتخذ إجراء أو يبدي طلبًا أو دفعًا أو دفاعًا كيديًّا.",
