      "useCase": "أنشئ أمراً على عريضة ودرّب على التظلم منه وأثره على التنفيذ.",
      "sourceNotes": [],
      "text": "1. للطالب إذا صدر الأمر برفض طلبه ولمن صدر عليه ولذوي الشأن الحق في التظلم من الأمر إلى المحكمة المختصة أو القاضي الذي أصدره -حسب الأحوال- إلا إذا نص القانون على خلاف ذلك ولا يمنع من نظر التظلم قيام الدعوى الأصلية أمام المحكمة.\n2. يجب أن يكون التظلم مسببًا.\n3. يقدم التظلم استقلالاً أو تبعًا للدعوى الأصلية، وذلك بالإجراءات التي ترفع بها الطلبات العارضة.\n4. يحكم في التظلم بتأييد الأمر أو بتعديله أو بإلغائه ويكون هذا الحكم قابلاً للطعن بالاستئناف فقط، فإن كان الأمر صادرًا من محكمة الاستئناف يكون التظلم منه أمام هيئة مغايرة لدى ذات المحكمة ويكون حكمها غير قابل للطعن بأي طريق من طرق الطعن.",
      "source": "قانون الإجراءات المدنية الإماراتي · المادة 141",
