      "sourceNotes": [],
      "text": "1. لا يجوز الطعن في الأحكام إلا من المحكوم عليه ولا يجوز ممن قبل الحكم صراحةً أو ضمنًا أو ممن قضي له بكل طلباته ما لم ينص القانون على غير ذلك.\n2. لا يضار الطاعن بطعنه.",
