      "text": "لا يجوز الطعن في الأحكام التي تصدر أثناء سير الدعوى ولا تنتهي بها الخصومة إلا بعد صدور الحكم المنهي للخصومة كلها وذلك فيما عدا الأحكام الوقتية والمستعجلة والصادرة بوقف الدعوى والأحكام القابلة للتنفيذ الجبري والأحكام الصادرة بعدم الاختصاص وكذلك الأحكام الصادرة بالاختصاص إذا لم يكن للمحكمة ولاية الحكم في الدعوى.",
