      "sourceNotes": [],
      "text": "1. يبدأ ميعاد الطعن في الحكم من اليوم التالي لتاريخ صدوره ما لم ينص القانون على غير ذلك ويبدأ هذا الميعاد من تاريخ إعلان الحكم إلى المحكوم عليه في الأحوال التي يكون فيها قد تخلف عن الحضور في جميع الجلسات المحددة لنظر الدعوى ولم يقدم مذكرة بدفاعه وكذلك إذا تخلف المحكوم عليه عن الحضور وعن تقديم مذكرة في جميع الجلسات التالية لتعجيل الدعوى بعد وقف السير فيها لأي سبب من الأسباب.\n2. يبدأ الميعاد من تاريخ إعلان الحكم إذا حدث سبب من أسباب انقطاع الخصومة وصدر الحكم دون اختصام من يقوم مقام الذي توفي أو فقد أهليته للخصومة أو زالت صفته.\n3. يكون إعلان الحكم وفق الأوضاع المقررة في المادتين (9) و(10) من هذا القانون.\n4. يترتب على عدم مراعاة مواعيد الطعن في الأحكام سقوط الحق في الطعن وتقضي المحكمة بالسقوط من تلقاء نفسها.",
      "source": "قانون الإجراءات المدنية الإماراتي · المادة 153",
      "sourceUrl": "https://uaelegislation.gov.ae/ar/legislations/1602",
