      "text": "1. يقف ميعاد الطعن بوفاة المحكوم عليه أو بفقد أهليته للتقاضي أو بزوال صفة من كان يباشر الخصومة عنه.\n2. لا يزول الوقف إلا بعد إعلان الحكم إلى الورثة جملة دون ذكر أسمائهم وصفاتهم وذلك في آخر موطن كان لمورثهم إذا لم يكن الورثة معروفين أو إعلانه إلى من يقوم مقام من فقد أهليته للتقاضي أو زالت صفته.\n3. في حال معرفة الورثة يكون الإعلان وفق الأوضاع المقررة في المادتين (9) و(10) من هذا القانون.",
