      "sourceNotes": [],
      "text": "1. إذا توفي المحكوم له أثناء ميعاد الطعن جاز لخصمه رفع الطعن وإعلانه إلى ورثته جملة دون ذكر أسمائهم وصفاتهم وذلك في آخر موطن كان لمورثهم ويعاد بعد ذلك إعلان الطعن لجميع الورثة بأسمائهم وصفاتهم قبل الجلسة المحددة لنظر الطعن أو في الميعاد الذي تُحدده المحكمة لإعلان الورثة الذين لم يعلنوا بالجلسة الأولى ولم يحضروها وإذا كانت الدعوى مستعجلة اكتفي بإعادة الإعلان إلى الورثة الظاهرين.\n2. إذا فقد المحكوم له أهلية التقاضي أثناء ميعاد الطعن أو زالت صفة من كان يباشر الخصومة عنه جاز رفع الطعن وإعلانه إلى من فقد أهليته أو زالت صفة من كان يباشر الخصومة عنه، ويعاد بعد ذلك إعلان الطعن إلى من يقوم مقام الخصم قبل الجلسة المحددة لنظر الطعن أو في الميعاد الذي تُحدده المحكمة وفق ما تقدم.\n3. يتم الإعلان في البندين (1) و(2) من هذه المادة وفق الأوضاع المقررة في المادتين (9) و(10) من هذا القانون.",
