      "sourceNotes": [],
      "text": "1. يجوز استئناف الأحكام والقرارات الصادرة في حدود النصاب الانتهائي من محاكم الدرجة الأولى بسبب مخالفة قواعد الاختصاص المتعلقة بالنظام العام أو وقوع بطلان في الحكم أو القرار أو بطلان في الإجراءات أثر في الحكم أو القرار.\n2. يجوز استئناف جميع الأحكام أو القرارات في حدود النصاب الانتهائي إذا كان الحكم أو القرار صادرًا على خلاف حكم أو قرار سابق لم يحز قوة الأمر المقضي، وفي هذه الحالة يعتبر الحكم أو القرار السابق مستأنفًا بقوة القانون إذا لم يكن قد صار انتهائيًّا عند رفع الاستئناف.\n3. على المستأنف في هذه الأحوال أن يودع خزانة المحكمة الاستئنافية عند تقديم الاستئناف تأمينًا قدره (2.000) ألفي درهم، وفي حال تعدد الطاعنين يكفي إيداع تأمين واحد إذا أقاموا طعنهم بصحيفة واحدة ولو اختلفت أسباب الطعن.\n4. لا يقبل مكتب إدارة الدعوى صحيفة الطعن إذا لم تصحب بما يثبت هذا الإيداع ويصادر التأمين بقوة القانون متى حكم بعدم جواز الاستئناف.",
