      "sourceNotes": [
        "وردت في المرفق عبارة «النصوص السابقة» قبل نص المادة؛ حُفظت كملاحظة مصدرية ولم تُدمج في النص التشريعي."
      ],
      "text": "1. يُرفع الاستئناف بصحيفة تودع مكتب إدارة الدعوى في المحكمة الاستئنافية المختصة وتقيد فوراً بالسجل المعد لذلك أو بقيدها إلكترونيًّا، ويجب أن تشتمل الصحيفة على بيان الحكم المستأنف وتاريخه وأسباب الاستئناف والطلبات، وإلا حُكم بعدم قبول الاستئناف.\n2. في غير أحوال القيد الإلكتروني يجب على المستأنف أن يقدم صوراً كافية من صحيفة الاستئناف بقدر عدد المستأنف عليهم وصورة لمكتب إدارة الدعوى، وأن يرفق بكل صورة المستندات المؤيدة لاستئنافه.",
      "source": "قانون الإجراءات المدنية الإماراتي · المادة 164",
