      "text": "1. على مكتب إدارة الدعوى بالمحكمة المرفوع إليها الاستئناف أن يطلب ضم ملف الدعوى الابتدائية إلكترونيًّا أو ورقيًّا في اليوم التالي لليوم الذي يرفع فيه الاستئناف.\n2. على مكتب إدارة الدعوى بالمحكمة الابتدائية التي أصدرت الحكم أن يرسل ملف الدعوى إلكترونيًّا أو ورقيًّا خلال (10) عشرة أيام على الأكثر من تاريخ طلبه وينقص هذا الميعاد إلى (3) ثلاثة أيام في الدعاوى المستعجلة.",
