      "sourceNotes": [],
      "text": "1. يجوز للمستأنف ضده حتى تاريخ الجلسة الأولى المحددة أمام مكتب إدارة الدعوى أو المحكمة -بحسب الأحوال- أن يرفع استئنافًا إما بالإجراءات المعتادة وإما بمذكرة مشتملة على أسباب استئنافه.\n2. يعتبر الاستئناف المشار إليه في الفقرة السابقة استئنافًا مقابلاً إذا رفع خلال ميعاد الاستئناف واستئنافًا فرعيًّا إذا رفع بعد الميعاد أو إذا كان رافعه قد قبل الحكم في وقت سابق على رفع الاستئناف الأصلي.\n3. يتبع الاستئناف الفرعي الاستئناف الأصلي ويسقط إذا تنازل المستأنف الأصلي عن استئنافه أو حكم بعدم قبول الاستئناف الأصلي شكلاً، أما الاستئناف المقابل فلا يزول بزوال الاستئناف الأصلي أيًّا كانت الطريقة التي رفع بها.",
