      "useCase": "حدّد سبب التماس إعادة النظر وميعاده وتأمينه وأثره على تنفيذ الحكم.",
      "sourceNotes": [],
      "text": "1. تفصل المحكمة بعد سماع الخصوم أولاً في جواز الالتماس فإذا قبلته حددت جلسة للمرافعة في الموضوع دون حاجة إلى إعلان جديد. على أنه يجوز لها أن تحكم في قبول الالتماس وفي الموضوع بحكم واحد إذا كان الخصوم قد قدموا أمامها طلباتهم في الموضوع ولا تعيد المحكمة النظر إلا في الطلبات التي تناولها الالتماس.\n2. لا يترتب على رفع الالتماس أو قبوله وقف تنفيذ الحكم، ومع ذلك يجوز للمحكمة التي تنظر الالتماس أن تأمر بوقف التنفيذ متى طلب ذلك وكان يخشى من التنفيذ وقوع ضرر جسيم يتعذر تداركه. ويجوز للمحكمة عندما تأمر بوقف التنفيذ أن توجب تقديم كفالة أو تأمر بما تراه كفيلاً بصيانة حق الملتمس ضده.\n3. لا يجوز التماس إعادة النظر في الحكم الذي صدر برفض الالتماس أو في الحكم في موضوع الدعوى بعد قبوله.",
      "source": "قانون الإجراءات المدنية الإماراتي · المادة 174",
      "sourceUrl": "https://uaelegislation.gov.ae/ar/legislations/1602",
