      "useCase": "حاكي طعن النقض: السبب، الميعاد، الرسم والتأمين، وقف التنفيذ، الإيداع، والنتيجة.",
      "sourceNotes": [
        "وردت في المرفق عبارة «النصوص السابقة» قبل نص المادة؛ حُفظت كملاحظة مصدرية ولم تُدمج في النص التشريعي."
      ],
      "text": "1. للخصوم أن يطعنوا بالنقض في الأحكام والقرارات الصادرة من محاكم الاستئناف إذا كانت قيمة الدعوى تجاوز (500,000) خمسمائة ألف درهم أو كانت غير مقدرة القيمة، وذلك في الأحوال الآتية:\n‌ أ. إذا كان الحكم أو القرار المطعون فيه مبنياً على مخالفة القانون أو الخطأ في تطبيقه أو في تأويله.\n‌ ب. إذا وقع بطلان في الحكم أو القرار أو في الإجراءات أثر في الحكم أو القرار.\n‌ ج. إذا كان الحكم أو القرار المطعون فيه قد صدر على خلاف قواعد الاختصاص.\n‌ د. إذا فصل في النزاع على خلاف حكم أو قرار آخر صدر في ذات الموضوع بين نفس الخصوم وحاز قوة الأمر المقضي به.\n‌ ه. خلو الحكم أو القرار من الأسباب أو عدم كفايتها أو غموضها.\n‌ و. إذا حكم بما لم يطلبه الخصوم أو بأكثر مما طلبوا.\n2. للخصوم أن يطعنوا أمام محكمة النقض في أي حكم أو قرار انتهائي - أيًّا كانت المحكمة التي أصدرته - فصل في نزاع خلافاً لحكم أو قرار آخر سبق أن صدر بين الخصوم أنفسهم وحاز قوة الأمر المقضي به.\n3. تكون الأحكام أو القرارات الصادرة عن محاكم الاستئناف في إجراءات التنفيذ غير قابلة للطعن بالنقض.",
      "source": "قانون الإجراءات المدنية الإماراتي · المادة 175",
      "sourceUrl": "https://uaelegislation.gov.ae/ar/legislations/1602",
