      "useCase": "حاكي طعن النقض: السبب، الميعاد، الرسم والتأمين، وقف التنفيذ، الإيداع، والنتيجة.",
      "sourceNotes": [
        "وردت في المرفق عبارة «النصوص السابقة» قبل نص المادة؛ حُفظت كملاحظة مصدرية ولم تُدمج في النص التشريعي."
      ],
      "text": "1. للنائب العام أن يطعن بطريق النقض أو التمييز من تلقاء نفسه أو بناءً على طلب من وزير العدل أو رئيس الجهة القضائية المحلية، حسب الأحوال، مرفقاً به أسباب الطعن، وذلك في الأحكام الانتهائية أيًّا كانت المحكمة التي أصدرتها والقرارات الصادرة من محاكم الاستئناف في غرفة المشورة، إذا كان الحكم أو القرار مبنياً على مخالفة القانون أو الخطأ في تطبيقه أو تأويله، وذلك في الأحوال الآتية:\n‌ أ. الأحكام والقرارات التي لا يجيز القانون للخصوم الطعن فيها.\n‌ ب. الأحكام والقرارات التي فوّت الخصوم ميعاد الطعن فيها أو نزلوا فيها عن الطعن أو رفعوا طعناً فيها قضى بعدم قبوله.\n2. يرفع النائب العام الطعن بصحيفة يوقعها خلال سنة من تاريخ صدور الحكم أو القرار، وتنظر المحكمة الطعن في غرفة المشورة بغير دعوة الخصوم، ويفيد الخصوم من هذا الطعن.",
