      "text": "1. يجوز للمطعون ضده أن يدخل في الطعن أي خصم في الدعوى التي صدر فيها الحكم المطعون فيه لم يوجه إليه الطعن ويكون إدخاله بإعلانه بالطعن على أن يتم هذا الإعلان خلال الميعاد المنصوص عليه في البند (3) من المادة (182) من هذا القانون.\n2. لمن أدخل في الطعن أن يودع مكتب إدارة الدعوى بالمحكمة مذكرة بدفاعه خلال (15) خمسة عشر يومًا من تاريخ إعلانه، وللطاعن الحق في الرد على هذه المذكرة طبقًا للمواعيد المقررة في المادة (182) من هذا القانون.",
