      "sourceNotes": [],
      "text": "1. يقوم قاضي التحضير بإعداد تقرير تلخيص بأوجه الطعن والرد عليها، وعلى مكتب إدارة الدعوى عرض ملف الدعوى بمجرد إيداع التقرير على الرئيس، لتحديد جلسة لنظر الطعن في غرفة مشورة، فإذا رأت المحكمة أن الطعن غير مقبول لسقوطه أو بطلان إجراءاته أو إقامته على غير الأسباب المبينة في المادة (175) من هذا القانون، أو لكون المسألة القانونية المثارة في الطعن سبق للمحكمة إصدار مبدأ قضائي فيها ولم تر ما يبرر العدول عنه، أمرت بعدم قبوله بقرار يثبت في محضر الجلسة مع إشارة موجزة لسبب القرار.\n2. إذا رأت المحكمة بأن الطعن جدير بالنظر حددت جلسة لنظره ليتلى فيها تقرير التلخيص وتحكم المحكمة في الطعن بعد المداولة وبغير مرافعة.\n3. إذا رأت المحكمة ضرورة المرافعة الشفوية فلها سماع أقوال المحامين عن الخصوم أو الخصوم أنفسهم.",
      "source": "قانون الإجراءات المدنية الإماراتي · المادة 185",
