      "useCase": "حاكي طعن النقض: السبب، الميعاد، الرسم والتأمين، وقف التنفيذ، الإيداع، والنتيجة.",
      "sourceNotes": [],
      "text": "مع عدم الإخلال بالبند (1) من المادة (185) واستثناءً من حكم المادة (189) من هذا القانون، يجوز للمحكمة الرجوع عن القرار الصادر منها في غرفة المشورة أو عن حكمها البات من تلقاء نفسها أو بناءً على طلب من الصادر ضده القرار أو الحكم، في أيٍّ من الأحوال الآتية:-\nأ‌. إذا شاب القرار أو الحكم خطأ إجرائي وقع من المحكمة أو أجهزتها المعاونة أثر في النتيجة التي انتهى إليه قرارها أو حكمها.\nب‌. إذا كان القرار أو الحكم مستندًا على قانون مُلغى، وكان من شأن تطبيق القانون الصحيح تغيير وجه الرأي في الدعوى.\nت‌. إذا صدر القرار أو الحكم مخالفًا لأيٍّ من المبادئ القضائية التي قررتها الهيئة أو الدوائر مجتمعة بالمحكمة حسب الأحوال، وذلك بدون العرض عليها، أو صدر مخالفًا للمبادئ التي استقرت عليها المحكمة أو التي أصدرتها هيئة توحيد المبادئ بين السلطات القضائية الاتحادية والمحلية.\n2. يُقدم طلب الرجوع من الصادر ضده القرار أو الحكم إلى مكتب إدارة الدعوى بالمحكمة الاتحادية العليا أو محكمة النقض أو محكمة التمييز حسب الأحوال، موقعًا من محام مقبول للمرافعة أمامها ومصحوبًا بتأمين مقداره (20.000) عشرين ألف درهم، وإذا كان الرجوع من تلقاء نفس المحكمة يُحيله رئيسها مصحوبًا بتقرير من المكتب الفني إلى الهيئة المنصوص عليها في البند (3) من هذه المادة.\n3. يُنظر طلب الرجوع أو إقرار الإحالة به المنصوص عليه في البند (2) من هذه المادة أمام هيئة مشكلة من (5) خمسة قضاة بالمحكمة من غير من شاركوا في إصدار القرار أو الحكم، وتصدر الهيئة منعقدة في غرفة المشورة قرارًا مسببًا بأغلبية (4) أربعة قضاة في طلب الرجوع، ويصادر مبلغ التأمين عند رفض الطلب. وفي حال قبول الطلب يحال إلى دائرة أخرى لنظر الطعن من جديد والفصل فيه، مع رد مبلغ التأمين إلى الطالب.\n4. في جميع الأحوال، تكون الإحالة أو تقديم طلب الرجوع لمرة واحدة فقط، ولا يجوز إحالته أو تقديمه بعد انقضاء سنة من تاريخ صدور القرار من غرفة المشورة أو الحكم البات.",
      "source": "قانون الإجراءات المدنية الإماراتي · المادة 190",
      "sourceUrl": "https://uaelegislation.gov.ae/ar/legislations/1602",
      "sourceFile": "Pasted markdown(4).md"
