      "sourceNotes": [],
      "text": "يُشترط لصحة العرض ما يأتي:-\n1. أن يوجه إلى ذي أهلية للتسلم أو من ينوب عنه.\n2. أن يوجه من شخص يصح منه القيام بالوفاء.\n3. أن يشمل العرض المبالغ والأعيان المستحقة والملحقات والمصروفات.\n4. أن يتحقق الشرط المتعلق بالالتزام.\n5. أن يتقدم المدين بالعرض للدائن نفسه أو في موطنه.",
      "source": "قانون الإجراءات المدنية الإماراتي · المادة 194",
      "sourceUrl": "https://uaelegislation.gov.ae/ar/legislations/1602",
      "sourceFile": "Pasted markdown(4).md"
