      "text": "1. إذا قضي بعدم قبول المخاصمة شكلاً أو رفضها موضوعًا حكم على الطالب بمصادرة التأمين مع التعويضات إن كان لها وجه.\n2. وإذا قضي بصحة المخاصمة حكم على القاضي أو عضو النيابة بالتضمينات والمصروفات وببطلان تصرفه وتكون الدولة مسؤولة عما يحكم به من التضمينات على القاضي أو عضو النيابة ولها حق الرجوع عليه ويجوز التنفيذ عليها مباشرةً بالحكم الصادر في دعوى المخاصمة.\n3. ومع ذلك لا يقضي ببطلان الحكم الصادر لمصلحة خصم آخر غير المدعي في دعوى المخاصمة إلا بعد إعلانه لإبداء أقواله ويجوز في هذه الحالة أن تصدر المحكمة في الدعوى الأصلية حكمًا جديدًا إذا رأت أنها صالحة للفصل وذلك بعد سماع أقوال الخصوم.",
